#!/usr/bin/env python3
"""Genera la richiesta preparatoria di un aggiornamento; non accede al server."""
import argparse,json,pathlib,subprocess,hashlib
R=pathlib.Path(__file__).resolve().parents[2]
p=argparse.ArgumentParser(description='Piano preparatorio proporzionato, nessun deploy')
p.add_argument('--base',required=True);p.add_argument('--candidato',default='HEAD');p.add_argument('--output',required=True);a=p.parse_args()
def git(*args):return subprocess.check_output(['git',*args],cwd=R).decode().strip()
base=git('rev-parse',a.base+'^{commit}');sha=git('rev-parse',a.candidato+'^{commit}');tree=git('rev-parse',sha+'^{tree}');files=git('diff','--name-only',base,sha).splitlines();code=[f for f in files if not f.startswith(('docs/','tests/','.github/'))]
checks=['Preflight runtime, spazio effettivo e baseline corrente; nessun riuso di approvazioni precedenti']
if any(f.endswith(('.js','.ts','.css','.scss','.blade.php')) for f in files):checks.append('Build Linux da lock, controlli JavaScript/Blade pertinenti e sonde UI sui percorsi cambiati')
if any(f.startswith(('app/','routes/','config/')) for f in files):checks.append('PHPUnit mirato ai componenti cambiati, con casi di autorizzazione/tenancy pertinenti, nella VM senza rete')
if any(f in ['composer.json','composer.lock','package.json','package-lock.json'] for f in files):checks.append('Dipendenze da lock, requisiti PHP/Node, autoload e regressioni dei componenti che usano le dipendenze cambiate')
migrations=[f for f in files if f.startswith('database/migrations/')]
if migrations:checks.append('Nuove DDL/DML sulla copia sintetica dello schema attuale; dati rappresentativi; guasto dopo mutazione e recupero coordinato provato')
if any(f.startswith(('scripts/deployment/','docs/operazioni/')) or f in ['deploy.sh'] for f in files):checks.append('Ripetere i casi interessati di guardiano/trasporto/deadline/recupero; SIGKILL e reboot quando il delta li coinvolge')
if not code and not migrations:checks.append('Delta documentale/test: controlli pertinenti; nessun rilascio applicativo implicito')
kit=R/'docs/operazioni/laboratorio-interno-2026-10-12';sig=hashlib.sha256((kit/'manifest.json').read_bytes()).hexdigest();dirty=git('status','--porcelain');v={'stato':'PREPARATORIO_NON_AUTORIZZA_RILASCIO','base_da_riconfermare_sul_server':base,'candidato':sha,'tree':tree,'file_delta':files,'modifiche_locali_presenti':bool(dirty),'migrazioni_da_esaminare':migrations,'controlli_richiesti':checks,'ambiente':'schedine-sviluppo-interno, MariaDB11.8.9, FileVault, nessun T7','ricevente_interno_prototipo_manifest_sha256':sig,'fasi':['sincronizzazione preservando modifiche','build e test proporzionati','prebuild offline e backup cifrato sul server','copia sul disco interno e restore indipendente nella VM interna','nuovi kit/piano/sigilli legati al candidato e migrazioni effettive','autorizzazione umana sul nuovo hash prima di manutenzione/deploy','checkpoint finale fresco, guardiano indipendente, installazione e DDL/DML','accettazione e sonde, recupero coordinato in caso di errore','monitoraggio e consuntivo; pulizia copie provate superflue'],'limiti':['Il kit modello è collaudato nel ricevente interno; ogni candidato futuro richiede composizione/sigilli e verifiche del delta','Non invocare direttamente vecchi piani C5 o depositi di verifica parzialmente puliti','Nessuna trasmissione o email implicita','Rollback tramite checkpoint coordinato, mai migrate:down/fresh sui dati operativi','Mai perdere scritture successive alla riapertura con un restore automatico obsoleto']};dest=pathlib.Path(a.output).resolve();assert dest.is_relative_to(R);dest.parent.mkdir(parents=True,exist_ok=True);assert not dest.exists();dest.write_text(json.dumps(v,indent=2,ensure_ascii=False)+'\n');print('Piano preparatorio: '+str(dest));print('SHA256: '+hashlib.sha256(dest.read_bytes()).hexdigest())
